O = "outputs"

def md_tables(path):
    if not os.path.exists(path): return []
    tabs, cur = [], []
    for line in open(path).read().splitlines():
        if line.startswith("|"): cur.append(line)
        elif cur: tabs.append(cur); cur = []
    if cur: tabs.append(cur)
    return tabs

def tbl(path, i, small=True, cls=""):
    T = md_tables(path)
    if i >= len(T): return f"<p><i>[table {i} of {path} not available]</i></p>"
    rows = [[c.strip() for c in l.strip().strip("|").split("|")] for l in T[i] if not re.match(r"^\|[\s\-|]+\|$", l)]
    h = "<table class='%s'><thead><tr>%s</tr></thead><tbody>" % (cls, "".join(f"<th>{html.escape(c)}</th>" for c in rows[0]))
    for r in rows[1:]:
        h += "<tr>" + "".join(f"<td>{html.escape(c)}</td>" for c in r) + "</tr>"
    return h + "</tbody></table>"

def img(path, w="100%", cap=""):
    if not os.path.exists(path): return f"<p><i>[figure {path} not available]</i></p>"
    b = base64.b64encode(open(path, "rb").read()).decode()
    ext = path.rsplit(".", 1)[-1].replace("jpg", "jpeg")
    return f"<figure><img src='data:image/{ext};base64,{b}' style='width:{w}'><figcaption>{cap}</figcaption></figure>"

def grab(path, pattern, default="?"):
    if not os.path.exists(path): return default
    m = re.search(pattern, open(path).read())
    return m.group(1) if m else default

